pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Each fuzz run deploys a fresh Bank-compliant caller (fresh address, zero balance).
        BankCaller caller = new BankCaller();
        // seed only steers the (irrelevant to rule) fuzzer's search space admission
        vm.assume(seed >= 0);

        bool ok;
        try caller.doAirDrop(c) { ok = true; } catch { ok = false; }

        // General rule: a Bank caller with zero balance always succeeds and holds exactly 20 tokens.
        assertTrue(ok && c.tokenBalance(address(caller)) == 20);
    }
}

contract BankCaller {
    function doAirDrop(C c) external {
        c.airDrop();
    }
}

