// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 reentries) public {
        uint256 n = bound(uint256(reentries), 2, 6);
        ReentrantAttacker atk = new ReentrantAttacker();
        atk.setTarget(address(c), n);
        vm.prank(address(atk));
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.tokenBalance(address(atk)) == 20);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 remaining;

    function setTarget(address t, uint256 n) external { target = C(t); remaining = n; }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function go() external {
        while (remaining > 0) {
            remaining--;
            try target.airDrop() {} catch {}
        }
    }

    receive() external payable {
        if (remaining > 0) {
            remaining--;
            try target.airDrop() {} catch {}
        }
    }
}
